  "prediction_basis_card_ids": ["C30","C33","C40","C03","C04","C19","C28","C55"],
  "claims": [
    {
      "claim": "Measured human absolute oral bioavailability values across the L1 contexts are at least 31.8% as central estimates, with most between 42% and 87%; no measured human value falls below the 20% threshold.",
      "card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C15","C16","C17","C18","C19","C20","C22","C23","C24","C25","C26","C27","C28","C29","C30","C31","C32","C33","C40"]
    },
    {
      "claim": "The query's piperazine-acyl-azetidinol side chain aligns with the DPP-4 inhibitor context; teneligliptin has good human oral bioavailability of 43–74% and rat bioavailability of 63–86%, supporting F ≥20%.",
      "card_ids": ["C30","C33","C40"]
    },
    {
      "claim": "Large, polar, piperazine-containing posaconazole reaches 42–56% fasted and 85–87% fed human bioavailability, showing that high molecular weight and high TPSA do not preclude F ≥20%.",
      "card_ids": ["C03","C04","C19","C28"]
    },
    {
      "claim": "L3 matched oral-versus-IV Cmax for isavuconazole (BAL4815) was 2.56 versus 2.55 µg/mL, supporting high oral exposure for an azole-like thiazole/fluorophenyl/nitrile compound; transfer to the query is moderate.",
      "card_ids": ["C55"]
    },
    {
      "claim": "L6 hepatic clearance and metabolic-stability records are molecule-specific for rosuvastatin, compound 72, KAF156, compound 4, larotrectinib, compound 21b, and compound 7k; none measure the query or establish query-specific first-pass loss, and CLint values alone are not threshold-relevant F evidence.",
      "card_ids": ["C87","C88","C89","C90","C91","C92","C93","C94","C95","C96","C97","C98"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F <20%; the low cat posaconazole F (C34) and low NNI-362 exposure (C53) are low-transferability and do not overturn the high prediction.",
      "card_ids": ["C34","C53"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C87","C88","C89","C90","C91","C92","C93","C94","C95","C96","C97","C98"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself; prediction relies on transfer from structurally related contexts.",
    "No query-specific hepatic clearance or metabolic-stability data; L6 records are for other molecules and cannot establish query first-pass loss.",
    "Prandial state for the query is unspecified; food effects could shift F, but all relevant human values remain ≥20%.",
    "Physicochemical prior flags high TPSA/HBA/ionization as potential absorption liabilities, but no affirmative low-F evidence is available.",
    "Low cat posaconazole F (C34) and low NNI-362 exposure (C53) are not transferable enough to establish a low-F outcome for the query."
  ],
  "decision_summary": "L6 hepatic clearance/metabolic-stability records are mechanistic and molecule-specific; none measure the query or establish query-specific first-pass loss, and CLint values alone are not threshold-relevant F evidence. The prior high prediction from L1 human absolute-F contexts and L3 isavuconazole exposure evidence remains supported; no new evidence overturns it, so prediction remains high at the F≥20% threshold with moderate confidence."
}

